    topBar(c,t("MŰHELYFEJLESZTÉS","WORKSHOP DEVELOPMENT","WERKSTATTAUSBAU","DESARROLLO DEL TALLER","DÉVELOPPEMENT ATELIER","工坊发展","SVILUPPO OFFICINA","DESENVOLVIMENTO DA OFICINA","ROZWÓJ WARSZTATU","WERKPLAATS ONTWIKKELING","DEZVOLTARE ATELIER","РАЗВИТИЕ МАСТЕРСКОЙ"));fill(c,Color.rgb(31,47,35),0,78,960,540);for(int yy=82;yy<540;yy+=28)for(int xx=0;xx<960;xx+=52)diamond(c,xx+(yy%56),yy,52,25,((xx+yy)/20)%2==0?Color.rgb(61,99,60):Color.rgb(55,89,55),Color.rgb(40,65,42));for(int xx=24;xx<936;xx+=30){fill(c,Color.rgb(88,61,35),xx,94,xx+16,119);fill(c,Color.rgb(117,78,42),xx+3,91,xx+13,116);}fill(c,Color.rgb(120,102,69),420,116,540,520);for(int yy=122;yy<510;yy+=34)fill(c,Color.rgb(142,123,82),425,yy,535,yy+18);
