  private void unit(Canvas c,float x,float y,int type,boolean enemy,int count,boolean selected){if(selected){fill(c,Color.argb(80,255,220,70),x-34,y-58,x+34,y+30);stroke(c,Color.rgb(255,221,72),2,x-34,y-58,x+34,y+30);}SpriteKit.worker(c,p,x,y,.82f,enemy?-1:1,type==2?3:0,animClock,enemy);text(c,"x"+count,x,y+20,12,Color.WHITE,Paint.Align.CENTER,true);}
  private void bar(Canvas c,float x,float y,int v,int max,int col){fill(c,Color.rgb(29,29,32),x,y,x+250,y+17);fill(c,col,x+2,y+2,x+2+246*Math.max(0,v)/(float)Math.max(1,max),y+15);stroke(c,Color.rgb(235,226,193),1,x,y,x+250,y+17);}
  private void combatAction(int kind){if(combatAnim>0)return;int count=selectedArmy==0?crew0:selectedArmy==1?crew1:crew2;if(count<=0)return;if(kind==0){int base=selectedArmy==0?7:selectedArmy==1?12:18;int dmg=base+heroAtk*4+weld*2+count*2+(morale/25);enemyHp-=dmg;score+=dmg*3;combatAnim=.35f;flash=.08f;fx.sparks(470,250,13,Color.rgb(255,195,70));enemyCounter();}else if(kind==1){guard=18+heroDef*7+count;ownHp=Math.min(220+heroDef*8,ownHp+8+heroDef*2);}else{if(tools>0){tools--;int dmg=38+engineering*6+weld*4;enemyHp-=dmg;combatAnim=.45f;fx.sparks(500,245,24,Color.rgb(97,201,255));enemyCounter();}else return;}turn++;selectedArmy=(selectedArmy+1)%3;enemyType=(enemyType+1)%3;if(enemyHp<=0){gold+=190+contracts*24;score+=720;blueprints+=(turn%3==0?1:0);morale=Math.min(100,morale+8);page=0;enemyHp=195+rivalPower*8;ownHp=220+heroDef*8;owner.reportScore(score);return;}if(ownHp<=0){morale=Math.max(20,morale-15);crew0=Math.max(3,crew0-2);crew1=Math.max(1,crew1-1);score=Math.max(0,score-180);page=0;ownHp=220+heroDef*8;enemyHp=195+rivalPower*8;}owner.reportScore(score);}
  private void enemyCounter(){int dmg=12+rivalPower*3+contracts/2;if(guard>0){dmg=Math.max(2,dmg-guard);guard=0;}ownHp-=dmg;}

  @Override void onGameDown(float x,float y){if(page==0){if(in(up,x,y))move(0,-1);else if(in(down,x,y))move(0,1);else if(in(left,x,y))move(-1,0);else if(in(right,x,y))move(1,0);else if(in(townBtn,x,y))page=1;else if(in(combatBtn,x,y))startBattle(195+rivalPower*10);else if(in(endTurn,x,y))doEndTurn();}else if(page==1){if(in(build0,x,y))upgrade(0);else if(in(build1,x,y))upgrade(1);else if(in(build2,x,y))upgrade(2);else if(in(rec0,x,y))recruit(0);else if(in(rec1,x,y))recruit(1);else if(in(rec2,x,y))recruit(2);else if(in(townMapBtn,x,y))page=0;}else{if(in(army0,x,y))selectedArmy=0;else if(in(army1,x,y))selectedArmy=1;else if(in(army2,x,y))selectedArmy=2;else if(in(attackBtn,x,y))combatAction(0);else if(in(defendBtn,x,y))combatAction(1);else if(in(skillBtn,x,y))combatAction(2);else if(in(mapBtn,x,y))page=0;}invalidate();}
  @Override void onGameMove(float x,float y){}
  @Override void onGameUp(float x,float y){}
